/**
 * This is the normal consumer close method.
 *
 * When a consumer that has acquired messages expects closes the messages that it has acquired should be removed from
 * the unacknowledgedMap and placed in msgToRequeue
 *
 * This test validates that the msgToRequeue map includes all the messages and none are left behind.
 *
 * @throws QpidException the visit interface throws this
 */
public void testRequeueDueToSubscriptionClosure() throws QpidException {
    acquireMessages(_referenceList);
    // Close subscription
    when(_consumer.isClosed()).thenReturn(true);
    final Map<Long, MessageInstance> msgToRequeue = new LinkedHashMap<Long, MessageInstance>();
    final Map<Long, MessageInstance> msgToResend = new LinkedHashMap<Long, MessageInstance>();
    // requeueIfUnableToResend doesn't matter here.
    _unacknowledgedMessageMap.visit(new ExtractResendAndRequeue(_unacknowledgedMessageMap, msgToRequeue, msgToResend));
    assertEquals("Message count for resend not correct.", 0, msgToResend.size());
    assertEquals("Message count for requeue not correct.", INITIAL_MSG_COUNT, msgToRequeue.size());
    assertEquals("Map was not emptied", 0, _unacknowledgedMessageMap.size());
}

public void testMessageCreditExhaustionSuspends() throws Exception {
    _creditManager = new Pre0_10CreditManager(0, 0, _protocolEngine);
    final FlowCreditManager.FlowCreditManagerListener flowListener = mock(FlowCreditManager.FlowCreditManagerListener.class);
    _creditManager.addStateListener(flowListener);
    _creditManager.setCreditLimits(0, 1);
    assertTrue("Creditmanager should be able to useCredit", _creditManager.useCreditForMessage(37));
    verify(flowListener, never()).creditStateChanged(anyBoolean());
    assertFalse("Creditmanager should not be able to useCredit", _creditManager.useCreditForMessage(37));
    verify(flowListener).creditStateChanged(false);
    _creditManager.restoreCredit(1, 0);
    verify(flowListener).creditStateChanged(true);
}

